import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskG solver = new TaskG();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskG {
        static final int MOD = 998244353;
        static final int ROOT = 3; // primitive root for MOD

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();
            int[] v = new int[10];
            for (int i = 0; i < k; i++) {
                int x = in.nextInt();
                v[x] = 1;
            }
            int[] ans = {1};
            int p = n / 2;
            while (true) {
                if (p % 2 != 0) {
                    ans = multiplyMod(ans, v);
                }
                p /= 2;
                if (p == 0) break;
                v = multiplyMod(v, v);
            }
            int res = 0;
            for (int x : ans) {
                res = (int) ((res + (long) x * x) % MOD);
            }
            out.println(res);
        }

        static int[] multiplyMod(int[] a, int[] b) {
            int need = a.length + b.length - 1;
            int n = 1;
            while (n < need) n <<= 1;
            int[] fa = new int[n];
            int[] fb = new int[n];
            for (int i = 0; i < a.length; i++) fa[i] = (a[i] % MOD + MOD) % MOD;
            for (int i = 0; i < b.length; i++) fb[i] = (b[i] % MOD + MOD) % MOD;
            ntt(fa, false);
            ntt(fb, false);
            for (int i = 0; i < n; i++) fa[i] = (int)((long)fa[i] * fb[i] % MOD);
            ntt(fa, true);
            int[] res = new int[need];
            for (int i = 0; i < need; i++) res[i] = fa[i];
            return res;
        }

        static void ntt(int[] a, boolean invert) {
            int n = a.length;
            // bit-reversal permutation
            for (int i = 1, j = 0; i < n; i++) {
                int bit = n >> 1;
                for (; (j & bit) != 0; bit >>= 1) {
                    j ^= bit;
                }
                j ^= bit;
                if (i < j) {
                    int temp = a[i];
                    a[i] = a[j];
                    a[j] = temp;
                }
            }
            for (int len = 2; len <= n; len <<= 1) {
                int wlen = powMod(ROOT, (MOD - 1) / len);
                if (invert) wlen = powMod(wlen, MOD - 2);
                for (int i = 0; i < n; i += len) {
                    int w = 1;
                    for (int j = 0; j < len / 2; j++) {
                        int u = a[i + j];
                        int v = (int)((long)a[i + j + len / 2] * w % MOD);
                        a[i + j] = (u + v) % MOD;
                        a[i + j + len / 2] = (u - v + MOD) % MOD;
                        w = (int)((long)w * wlen % MOD);
                    }
                }
            }
            if (invert) {
                int invN = powMod(n, MOD - 2);
                for (int i = 0; i < n; i++) {
                    a[i] = (int)((long)a[i] * invN % MOD);
                }
            }
        }

        static int powMod(int a, int e) {
            int res = 1;
            while (e > 0) {
                if ((e & 1) == 1) res = (int)((long)res * a % MOD);
                a = (int)((long)a * a % MOD);
                e >>= 1;
            }
            return res;
        }
    }

    static class InputReader {
        final InputStream is;
        final byte[] buf = new byte[1024];
        int pos;
        int size;

        public InputReader(InputStream is) {
            this.is = is;
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c))
                c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res = res * 10 + c - '0';
                c = read();
            } while (!isWhitespace(c));
            return res * sign;
        }

        int read() {
            if (size == -1)
                throw new InputMismatchException();
            if (pos >= size) {
                pos = 0;
                try {
                    size = is.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (size <= 0)
                    return -1;
            }
            return buf[pos++] & 255;
        }

        static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
